<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import {
  Boxes, FileCode2, GitBranch, GitCompare, GitFork, Package, Play, RefreshCw, Rocket,
  Save, Search, ShieldCheck, Tag, Trash2, UploadCloud, Wrench
} from 'lucide-vue-next'
import { ApiError, api } from '../services/api'
import { useDialogStore } from '../stores/dialog'
import { useToastStore } from '../stores/toast'
import type { GitHubConnection, PaginatedResponse, Repository } from '../types/api'

type Tab='repositories'|'branches'|'releases'|'ghcr'|'cleanup'
interface BootstrapFile { path:string; status:string; sha:string|null; action:'keep'|'replace'; content:string; diff:string }
interface BootstrapPreview { branch:string; template:string; files:BootstrapFile[] }
interface TreeItem { path:string; mode:string; type:string; sha:string; size?:number }
interface PublishingChannel { id:string; name:string; kind:string; config:Record<string,unknown>; enabled:boolean }
interface GhcrVersion { id:number; name:string; tags:string[]; created_at:string|null; updated_at:string|null; metadata:Record<string,unknown> }
interface PackageDetail { name:string; package_type:string; visibility:string|null; created_at:string|null; updated_at:string|null; version_count:number; tag_count:number; versions:GhcrVersion[] }
interface CleanupCandidate { id:string; resource_type:string; resource_key:string; action_class:string; reason:string; protected:boolean; selected:boolean; size_bytes:number|null }
interface CleanupAnalysis { id:string; reference:string; status:string; estimated_reclaimed_bytes:number; dry_run:Record<string,unknown>; candidates:CleanupCandidate[] }

const dialogs=useDialogStore(); const toasts=useToastStore(); const loading=ref(true); const busy=ref(''); const tab=ref<Tab>('repositories');
const connections=ref<GitHubConnection[]>([]); const repositories=ref<Repository[]>([]); const selectedConnectionId=ref(''); const selectedRepositoryId=ref(''); const repositoryQuery=ref('');
const branches=ref<Array<Record<string,unknown>>>([]); const tree=ref<TreeItem[]>([]); const fileSha=ref(''); const bootstrapPreview=ref<BootstrapPreview|null>(null); const compareResult=ref<Record<string,unknown>|null>(null); const actions=reactive({workflows:[] as unknown[],runs:[] as unknown[],artifacts:[] as unknown[],caches:[] as unknown[]}); const channels=ref<PublishingChannel[]>([]); const packages=ref<Array<Record<string,unknown>>>([]); const packageDetail=ref<PackageDetail|null>(null); const cleanupAnalyses=ref<CleanupAnalysis[]>([]); const selectedCleanupId=ref(''); const cleanupSelectedIds=ref<string[]>([]);
const repoForm=reactive({owner:'',name:'',description:'',private:true,default_branch:'main',template:'empty'}); const bootstrapForm=reactive({branch:'main',template:'docker_ghcr'}); const branchForm=reactive({branch:'',base_branch:'main',set_default:false}); const protectionForm=reactive({branch:'main',require_pull_request:true,approvals:1,enforce_admins:true,required_status_checks:'',allow_force_pushes:false,allow_deletions:false}); const compareForm=reactive({base:'main',head:''}); const treeForm=reactive({branch:'main',prefix:''}); const fileForm=reactive({branch:'main',path:'',message:'chore: atualizar arquivo pelo ARGWS Git Monitor',content:''}); const releaseForm=reactive({tag_name:'',name:'',body:'',target_commitish:'main',create_tag:true,draft:false,prerelease:false,make_latest:true,channel_ids:[] as string[]}); const workflowForm=reactive({workflow:'',ref:'main'}); const channelForm=reactive({name:'GitHub Release',kind:'github_release',configText:'{}',secretText:'{}'}); const packageForm=reactive({owner:'',package_name:'',preserve_tags:'latest'}); const cleanupForm=reactive({criteriaText:'{}',preservationText:'{"preserve_default_branch":true,"preserve_latest_release":true,"preserve_last_releases":5,"preserve_protected_branches":true,"preserve_deployment_refs":true,"preserve_latest_image":true}',checkpointText:'{}'});
const selectedConnection=computed(()=>connections.value.find(x=>x.id===selectedConnectionId.value)||null); const selectedRepository=computed(()=>repositories.value.find(x=>x.id===selectedRepositoryId.value)||null); const filteredRepositories=computed(()=>{const q=repositoryQuery.value.trim().toLowerCase();return q?repositories.value.filter(x=>x.full_name.toLowerCase().includes(q)):repositories.value}); const selectedCleanup=computed(()=>cleanupAnalyses.value.find(x=>x.id===selectedCleanupId.value)||null)
function message(error:unknown){return error instanceof ApiError?error.message:String(error)}
function jsonObject(value:string){const parsed=JSON.parse(value||'{}') as unknown;if(!parsed||Array.isArray(parsed)||typeof parsed!=='object')throw new Error('JSON deve ser objeto.');return parsed as Record<string,unknown>}
function bytes(value:number|null|undefined){if(!value)return '—';const units=['B','KB','MB','GB','TB'];let v=value,i=0;while(v>=1024&&i<units.length-1){v/=1024;i++}return `${v.toFixed(i?1:0)} ${units[i]}`}
async function run(key:string,fn:()=>Promise<void>){busy.value=key;try{await fn()}catch(error){toasts.error('Operação recusada',message(error))}finally{busy.value=''}}
async function loadRepos(){const all:Repository[]=[];let p=1,pages=1;do{const r=await api.get<PaginatedResponse<Repository>>(`/repositories?page=${p}&page_size=100`);all.push(...r.items);pages=r.pages;p++}while(p<=pages);return all}
async function load(){loading.value=true;try{const [c,r,ch]=await Promise.all([api.get<GitHubConnection[]>('/github/connections'),loadRepos(),api.get<PublishingChannel[]>('/platform/publishing-channels')]);connections.value=c.filter(x=>x.status!=='demo');repositories.value=r;channels.value=ch;if(!selectedConnectionId.value)selectedConnectionId.value=connections.value[0]?.id||'';if(!selectedRepositoryId.value)selectedRepositoryId.value=repositories.value[0]?.id||'';packageForm.owner=selectedConnection.value?.github_login||'';repoForm.owner=selectedConnection.value?.github_login||''}catch(error){toasts.error('Falha ao carregar GitHub Tools',message(error))}finally{loading.value=false}}
watch(selectedConnectionId,()=>{packageForm.owner=selectedConnection.value?.github_login||'';repoForm.owner=selectedConnection.value?.github_login||''});watch(selectedRepositoryId,()=>{const repo=selectedRepository.value;if(repo){bootstrapForm.branch=repo.default_branch;branchForm.base_branch=repo.default_branch;protectionForm.branch=repo.default_branch;compareForm.base=repo.default_branch;treeForm.branch=repo.default_branch;fileForm.branch=repo.default_branch;releaseForm.target_commitish=repo.default_branch;workflowForm.ref=repo.default_branch}branches.value=[];tree.value=[];bootstrapPreview.value=null;packageDetail.value=null;cleanupAnalyses.value=[];selectedCleanupId.value=''})

async function createRepository(){const connection=selectedConnection.value;if(!connection)return;await run('repo-create',async()=>{const result=await api.post<{full_name:string;html_url:string}>(`/github-tools-v2/connections/${connection.id}/repositories`,{...repoForm,owner:repoForm.owner||connection.github_login});toasts.success('Repositório criado',result.full_name);await load()})}
async function changeVisibility(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;const privateValue=!repo.private;const accepted=await dialogs.askConfirmation({title:privateValue?'Tornar repositório privado?':'Tornar repositório público?',message:`${repo.full_name} será alterado diretamente no GitHub.`,tone:privateValue?'warning':'danger',confirmLabel:privateValue?'Tornar privado':'Tornar público'});if(!accepted)return;await run('repo-visibility',async()=>{await api.patch(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}`,{private:privateValue});toasts.success('Visibilidade atualizada');await load()})}
async function previewBootstrap(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;await run('bootstrap-preview',async()=>{bootstrapPreview.value=await api.post<BootstrapPreview>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/bootstrap/preview`,bootstrapForm)})}
async function applyBootstrap(){const connection=selectedConnection.value,repo=selectedRepository.value,preview=bootstrapPreview.value;if(!connection||!repo||!preview)return;const files=preview.files.filter(x=>x.action==='replace').map(x=>({path:x.path,content:x.content,sha:x.sha}));const accepted=await dialogs.askConfirmation({title:'Aplicar estrutura no repositório?',message:`${files.length} arquivo(s) serão criados/substituídos em ${repo.full_name}/${preview.branch}.`,tone:'warning',confirmLabel:'Aplicar estrutura'});if(!accepted)return;await run('bootstrap-apply',async()=>{const result=await api.post<{applied:unknown[];skipped:unknown[]}>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/bootstrap/apply`,{branch:preview.branch,files});toasts.success('Bootstrap aplicado',`${result.applied.length} arquivo(s) alterado(s).`);await previewBootstrap()})}

async function loadBranches(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;branches.value=await api.get<Array<Record<string,unknown>>>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/branches`)}
async function createBranch(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;await run('branch-create',async()=>{await api.post(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/branches`,branchForm);toasts.success('Branch criada',branchForm.branch);await loadBranches()})}
async function deleteBranch(name:string){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;const expected=`EXCLUIR ${repo.full_name}:${name}`;const confirmation=await dialogs.askText({title:'Excluir branch?',message:`A branch ${name} será excluída de ${repo.full_name}.`,tone:'danger',confirmLabel:'Excluir branch',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run(`branch-delete-${name}`,async()=>{await api.delete(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/branches/${encodeURIComponent(name)}?confirmation=${encodeURIComponent(confirmation)}`);toasts.success('Branch removida',name);await loadBranches()})}
async function protectBranch(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;await run('protect',async()=>{await api.put(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/branches/${encodeURIComponent(protectionForm.branch)}/protection`,{...protectionForm,required_status_checks:protectionForm.required_status_checks.split(',').map(x=>x.trim()).filter(Boolean)});toasts.success('Proteção aplicada',protectionForm.branch)})}
async function compareBranches(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;compareResult.value=await api.get<Record<string,unknown>>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/compare?base=${encodeURIComponent(compareForm.base)}&head=${encodeURIComponent(compareForm.head)}`)}

async function loadTree(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;tree.value=await api.get<TreeItem[]>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/tree?branch=${encodeURIComponent(treeForm.branch)}&prefix=${encodeURIComponent(treeForm.prefix)}`)}
async function readFile(path:string){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;const result=await api.get<{path:string;content:string;sha:string}>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/files/${path}?branch=${encodeURIComponent(treeForm.branch)}`);fileForm.path=result.path;fileForm.content=result.content;fileForm.branch=treeForm.branch;fileSha.value=result.sha}
async function saveFile(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo||!fileForm.path)return;await run('file-save',async()=>{const result=await api.put<{sha:string}>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/files/${fileForm.path}`,{branch:fileForm.branch,message:fileForm.message,content:fileForm.content,sha:fileSha.value||null});fileSha.value=result.sha;toasts.success('Arquivo salvo',fileForm.path);await loadTree()})}
async function deletePath(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo||!treeForm.prefix)return;const expected=`EXCLUIR ${repo.full_name}:${treeForm.prefix}`;const confirmation=await dialogs.askText({title:'Excluir caminho do repositório?',message:`${treeForm.prefix} será removido de ${repo.full_name}.`,tone:'danger',confirmLabel:'Excluir caminho',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run('path-delete',async()=>{const result=await api.post<{deleted:unknown[]}>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/paths/delete`,{branch:treeForm.branch,path:treeForm.prefix,confirmation});toasts.success('Caminho removido',`${result.deleted.length} item(ns).`);await loadTree()})}

async function createChannel(){await run('channel',async()=>{const c=await api.post<PublishingChannel>('/platform/publishing-channels',{name:channelForm.name,kind:channelForm.kind,config:jsonObject(channelForm.configText),secret:jsonObject(channelForm.secretText),enabled:true});channels.value.push(c);channelForm.secretText='{}';toasts.success('Canal criado',c.name)})}
async function createRelease(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;await run('release',async()=>{const r=await api.post<{release:Record<string,unknown>;channel_results:unknown[]}>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/releases`,releaseForm);toasts.success('Release processada',`${String(r.release.tag_name||releaseForm.tag_name)} · ${r.channel_results.length} canal(is).`)})}
async function dispatchWorkflow(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;await run('workflow',async()=>{await api.post(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/workflows/dispatch`,workflowForm);toasts.success('Workflow disparado',workflowForm.workflow)})}
async function loadActions(){const connection=selectedConnection.value,repo=selectedRepository.value;if(!connection||!repo)return;const [w,r,a,c]=await Promise.all([api.get<unknown[]>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/workflows`),api.get<unknown[]>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/workflow-runs`),api.get<unknown[]>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/artifacts`),api.get<unknown[]>(`/github-tools-v2/connections/${connection.id}/repositories/${repo.full_name}/actions-cache`)]);actions.workflows=w;actions.runs=r;actions.artifacts=a;actions.caches=c}

async function loadPackages(){const connection=selectedConnection.value;if(!connection)return;const owner=packageForm.owner||connection.github_login;packages.value=await api.get<Array<Record<string,unknown>>>(`/github-tools-v2/connections/${connection.id}/ghcr/packages?owner=${encodeURIComponent(owner)}`)}
async function loadPackageDetail(name:string){const connection=selectedConnection.value;if(!connection)return;packageForm.package_name=name;const owner=packageForm.owner||connection.github_login;packageDetail.value=await api.get<PackageDetail>(`/github-tools-v2/connections/${connection.id}/ghcr/packages/${encodeURIComponent(name)}?owner=${encodeURIComponent(owner)}`)}
async function deleteByTag(tag:string){const connection=selectedConnection.value;if(!connection||!packageForm.package_name)return;const owner=packageForm.owner||connection.github_login;const expected=`EXCLUIR TAG ${owner}/${packageForm.package_name}:${tag}`;const confirmation=await dialogs.askText({title:'Excluir tag do GHCR?',message:`A versão associada à tag ${tag} será removida quando a API do GitHub permitir.`,tone:'danger',confirmLabel:'Excluir tag',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run(`ghcr-tag-${tag}`,async()=>{await api.delete(`/github-tools-v2/connections/${connection.id}/ghcr/packages/${encodeURIComponent(packageForm.package_name)}/tags/${encodeURIComponent(tag)}?owner=${encodeURIComponent(owner)}&confirmation=${encodeURIComponent(confirmation)}`);toasts.success('Tag removida',tag);await loadPackageDetail(packageForm.package_name)})}
async function deleteVersion(version:GhcrVersion){const connection=selectedConnection.value;if(!connection||!packageForm.package_name)return;const owner=packageForm.owner||connection.github_login;const expected=`EXCLUIR VERSAO ${owner}/${packageForm.package_name}#${version.id}`;const confirmation=await dialogs.askText({title:'Excluir versão do GHCR?',message:`Versão ${version.id} de ${owner}/${packageForm.package_name}.`,tone:'danger',confirmLabel:'Excluir versão',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run(`ghcr-version-${version.id}`,async()=>{await api.delete(`/github-tools-v2/connections/${connection.id}/ghcr/packages/${encodeURIComponent(packageForm.package_name)}/versions/${version.id}?owner=${encodeURIComponent(owner)}&confirmation=${encodeURIComponent(confirmation)}`);toasts.success('Versão removida',String(version.id));await loadPackageDetail(packageForm.package_name)})}
async function deleteAllVersions(){const connection=selectedConnection.value;if(!connection||!packageForm.package_name)return;const owner=packageForm.owner||connection.github_login;const expected=`EXCLUIR TODAS AS VERSOES ${owner}/${packageForm.package_name}`;const confirmation=await dialogs.askText({title:'Limpar versões do package?',message:`As tags informadas em “preservar” serão mantidas. As demais versões elegíveis poderão ser removidas.`,tone:'danger',confirmLabel:'Limpar versões',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run('ghcr-all',async()=>{const result=await api.post<{deleted:number[];preserved:unknown[];failed:unknown[]}>(`/github-tools-v2/connections/${connection.id}/ghcr/packages/${encodeURIComponent(packageForm.package_name)}/delete-all?owner=${encodeURIComponent(owner)}`,{confirmation,preserve_tags:packageForm.preserve_tags.split(',').map(x=>x.trim()).filter(Boolean)});toasts.success('Limpeza GHCR concluída',`${result.deleted.length} removida(s), ${result.preserved.length} preservada(s), ${result.failed.length} falha(s).`);await loadPackageDetail(packageForm.package_name)})}
async function deletePackage(){const connection=selectedConnection.value;if(!connection||!packageForm.package_name)return;const owner=packageForm.owner||connection.github_login;const expected=`${owner}/${packageForm.package_name}`;const confirmation=await dialogs.askText({title:'Excluir package inteiro?',message:'Esta operação remove integralmente o package do GHCR. Digite o nome completo para confirmar.',tone:'danger',confirmLabel:'Excluir package',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run('ghcr-package',async()=>{await api.delete(`/github-tools-v2/connections/${connection.id}/ghcr/packages/${encodeURIComponent(packageForm.package_name)}?owner=${encodeURIComponent(owner)}&confirmation=${encodeURIComponent(confirmation)}`);packageDetail.value=null;toasts.success('Package removido',expected);await loadPackages()})}

async function loadCleanup(){const repo=selectedRepository.value;if(!repo)return;cleanupAnalyses.value=await api.get<CleanupAnalysis[]>(`/platform/cleanup?repository_id=${repo.id}&limit=20`);if(cleanupAnalyses.value.length&&!selectedCleanupId.value)selectedCleanupId.value=cleanupAnalyses.value[0].id}
async function analyzeCleanup(){const repo=selectedRepository.value;if(!repo)return;await run('cleanup-analyze',async()=>{const r=await api.post<{job_id:string}>('/platform/cleanup/analyze',{repository_id:repo.id,profile_id:null,criteria:jsonObject(cleanupForm.criteriaText),preservation_rules:jsonObject(cleanupForm.preservationText),canonical_checkpoint:jsonObject(cleanupForm.checkpointText)});toasts.success('Análise enfileirada',`Job ${r.job_id}; nenhum DELETE nesta etapa.`)})}
async function refreshCleanup(){await loadCleanup();if(selectedCleanupId.value){const detail=await api.get<CleanupAnalysis>(`/platform/cleanup/${selectedCleanupId.value}`);const i=cleanupAnalyses.value.findIndex(x=>x.id===detail.id);if(i>=0)cleanupAnalyses.value[i]=detail}}
async function saveCleanupSelection(){if(!selectedCleanup.value)return;const updated=await api.put<CleanupAnalysis>(`/platform/cleanup/${selectedCleanup.value.id}/selection`,{candidate_ids:cleanupSelectedIds.value});const i=cleanupAnalyses.value.findIndex(x=>x.id===updated.id);if(i>=0)cleanupAnalyses.value[i]=updated}
async function cleanupDryRun(){if(!selectedCleanup.value)return;await run('cleanup-dry',async()=>{await saveCleanupSelection();const r=await api.post<{job_id:string}>(`/platform/cleanup/${selectedCleanup.value!.id}/dry-run`,{});toasts.success('Dry Run iniciado',`Job ${r.job_id}`)})}
async function cleanupExecute(){const item=selectedCleanup.value;if(!item)return;const expected=`EXECUTAR ${item.reference}`;const confirmation=await dialogs.askText({title:'Executar plano de limpeza?',message:'Somente o plano aprovado será enviado para execução. Itens protegidos continuam bloqueados.',tone:'danger',confirmLabel:'Executar cleanup',promptLabel:'Confirmação obrigatória',promptExpected:expected,promptPlaceholder:expected});if(confirmation!==expected)return;await run('cleanup-execute',async()=>{await saveCleanupSelection();const r=await api.post<{job_id:string}>(`/platform/cleanup/${item.id}/execute`,{confirmation,create_backup:true});toasts.success('Cleanup iniciado',`Job ${r.job_id}`)})}

onMounted(load)
</script>

<template><div class="page-stack tools-page">
  <section class="page-heading"><div><span class="eyebrow">CENTRAL GITHUB ONLINE</span><h2>GitHub Tools</h2><p>Administração online nativa do GitHub/GHCR, sem subprocessos PowerShell e sem repositório hardcoded.</p></div><button class="button secondary" :disabled="loading" @click="load"><RefreshCw :size="16"/>Atualizar</button></section>
  <nav class="tabs"><button :class="{active:tab==='repositories'}" @click="tab='repositories'"><Boxes :size="15"/>Repositórios</button><button :class="{active:tab==='branches'}" @click="tab='branches'"><GitBranch :size="15"/>Branches & Arquivos</button><button :class="{active:tab==='releases'}" @click="tab='releases'"><Tag :size="15"/>Releases & Actions</button><button :class="{active:tab==='ghcr'}" @click="tab='ghcr'"><Package :size="15"/>GHCR</button><button :class="{active:tab==='cleanup'}" @click="tab='cleanup'"><Trash2 :size="15"/>Cleanup</button></nav>
  <section class="control-strip"><label class="field"><span>Conexão GitHub</span><select v-model="selectedConnectionId"><option v-for="connection in connections" :key="connection.id" :value="connection.id">{{connection.name}} · @{{connection.github_login}}</option></select></label><label class="field"><span>Filtrar repositório</span><div class="input-with-icon"><Search :size="15"/><input v-model="repositoryQuery" placeholder="owner/repo"/></div></label><label class="field"><span>Repositório</span><select v-model="selectedRepositoryId"><option value="">Nenhum / criar novo</option><option v-for="repo in filteredRepositories" :key="repo.id" :value="repo.id">{{repo.full_name}}</option></select></label></section>

  <template v-if="tab==='repositories'">
    <section class="grid cols-2"><article class="tool-card"><header><GitFork :size="19"/><div><strong>Repository Manager</strong><span>Criação totalmente online por API GitHub.</span></div></header><div class="grid cols-2"><label class="field"><span>Owner</span><input v-model="repoForm.owner"/></label><label class="field"><span>Nome</span><input v-model="repoForm.name"/></label></div><label class="field"><span>Descrição</span><input v-model="repoForm.description"/></label><div class="grid cols-2"><label class="field"><span>Visibilidade</span><select v-model="repoForm.private"><option :value="true">Private</option><option :value="false">Public</option></select></label><label class="field"><span>Default branch</span><input v-model="repoForm.default_branch"/></label></div><label class="field"><span>Template</span><select v-model="repoForm.template"><option value="empty">Vazio</option><option value="readme">README básico</option><option value="docker">Docker</option><option value="docker_ghcr">Docker + GHCR</option><option value="custom">Personalizado</option></select></label><button class="button primary" :disabled="busy==='repo-create'||!repoForm.name||!selectedConnection" @click="createRepository"><Rocket :size="15"/>Criar repositório</button></article>
      <article class="tool-card"><header><ShieldCheck :size="19"/><div><strong>Repository Settings</strong><span>Visibilidade e estado do repositório selecionado.</span></div></header><template v-if="selectedRepository"><p><b>{{selectedRepository.full_name}}</b></p><div class="facts"><span>{{selectedRepository.private?'Private':'Public'}}</span><span>{{selectedRepository.default_branch}}</span><span>{{selectedRepository.archived?'Archived':'Active'}}</span></div><button class="button secondary" @click="changeVisibility">Tornar {{selectedRepository.private?'público':'privado'}}</button></template><p v-else class="empty">Selecione um repositório para administrar.</p></article>
    </section>
    <section class="tool-card wide"><header><UploadCloud :size="19"/><div><strong>Repository Bootstrap / Docker & GHCR Bootstrap</strong><span>Preview obrigatório antes de criar ou substituir arquivos.</span></div></header><div class="grid cols-2"><label class="field"><span>Branch</span><input v-model="bootstrapForm.branch"/></label><label class="field"><span>Template</span><select v-model="bootstrapForm.template"><option value="readme">README</option><option value="docker">Docker</option><option value="docker_ghcr">Docker + GHCR</option><option value="custom">Custom</option></select></label></div><div class="actions"><button class="button secondary" :disabled="!selectedRepository||busy==='bootstrap-preview'" @click="previewBootstrap">Analisar estrutura</button><button class="button primary" :disabled="!bootstrapPreview||busy==='bootstrap-apply'" @click="applyBootstrap">Aplicar estrutura</button></div><div v-if="bootstrapPreview" class="preview-list"><article v-for="file in bootstrapPreview.files" :key="file.path"><div><code>{{file.path}}</code><span class="status">{{file.status}}</span></div><select v-model="file.action"><option value="keep">Manter existente</option><option value="replace">{{file.status==='CREATE'?'Criar':'Substituir'}}</option></select><details v-if="file.diff"><summary>Visualizar diferença</summary><pre>{{file.diff}}</pre></details></article></div></section>
  </template>

  <template v-else-if="tab==='branches'">
    <section class="grid cols-2"><article class="tool-card"><header><GitBranch :size="19"/><div><strong>Branch Manager</strong><span>Criar, definir default e excluir com confirmação.</span></div></header><div class="grid cols-2"><label class="field"><span>Branch</span><input v-model="branchForm.branch"/></label><label class="field"><span>Base</span><input v-model="branchForm.base_branch"/></label></div><label class="check"><input v-model="branchForm.set_default" type="checkbox"/>Definir como default</label><div class="actions"><button class="button primary" @click="createBranch">Criar/garantir</button><button class="button secondary" @click="loadBranches">Atualizar branches</button></div><div class="branch-list"><div v-for="branch in branches" :key="String(branch.name)"><div><b>{{branch.name}}</b><small>{{String(branch.sha||'').slice(0,10)}} · {{branch.default?'default · ':''}}{{branch.protected?'protected':'unprotected'}}</small></div><button v-if="!branch.default" class="button ghost danger-text" @click="deleteBranch(String(branch.name))">Excluir</button></div></div></article>
      <article class="tool-card"><header><ShieldCheck :size="19"/><div><strong>Branch Protection</strong><span>Configuração por branch, não presa à main.</span></div></header><label class="field"><span>Branch</span><input v-model="protectionForm.branch"/></label><div class="checks"><label class="check"><input v-model="protectionForm.require_pull_request" type="checkbox"/>Exigir PR</label><label class="check"><input v-model="protectionForm.enforce_admins" type="checkbox"/>Admins</label><label class="check"><input v-model="protectionForm.allow_force_pushes" type="checkbox"/>Permitir force push</label><label class="check"><input v-model="protectionForm.allow_deletions" type="checkbox"/>Permitir exclusão</label></div><label class="field"><span>Aprovações</span><input v-model.number="protectionForm.approvals" type="number" min="0" max="6"/></label><label class="field"><span>Status checks (vírgula)</span><input v-model="protectionForm.required_status_checks"/></label><button class="button primary" @click="protectBranch">Aplicar proteção</button></article></section>
    <section class="tool-card wide"><header><GitCompare :size="19"/><div><strong>Compare</strong><span>Comparação real pela API GitHub.</span></div></header><div class="grid cols-2"><label class="field"><span>Base</span><input v-model="compareForm.base"/></label><label class="field"><span>Head</span><input v-model="compareForm.head"/></label></div><button class="button secondary" @click="compareBranches">Comparar</button><pre v-if="compareResult">{{JSON.stringify(compareResult,null,2)}}</pre></section>
    <section class="tool-card wide"><header><FileCode2 :size="19"/><div><strong>Repository Files</strong><span>Navegar, ler, criar/editar e excluir caminhos remotamente.</span></div></header><div class="grid cols-3"><label class="field"><span>Branch</span><input v-model="treeForm.branch"/></label><label class="field span-2"><span>Filtro/caminho</span><input v-model="treeForm.prefix" placeholder="backend/app ou README.md"/></label></div><div class="actions"><button class="button secondary" @click="loadTree"><Search :size="15"/>Listar árvore</button><button class="button ghost danger-text" @click="deletePath"><Trash2 :size="15"/>Excluir caminho</button></div><div v-if="tree.length" class="tree-list"><button v-for="item in tree.slice(0,300)" :key="item.path" :disabled="item.type!=='blob'" @click="item.type==='blob'&&readFile(item.path)"><code>{{item.path}}</code><span>{{item.type}} · {{item.size||0}} B</span></button></div><div class="file-editor"><div class="grid cols-2"><label class="field"><span>Branch</span><input v-model="fileForm.branch"/></label><label class="field"><span>Arquivo</span><input v-model="fileForm.path"/></label></div><label class="field"><span>Mensagem</span><input v-model="fileForm.message"/></label><label class="field"><span>Conteúdo UTF-8</span><textarea v-model="fileForm.content" class="code-editor"/></label><small v-if="fileSha">SHA atual: {{fileSha}}</small><button class="button primary" @click="saveFile"><Save :size="15"/>Salvar arquivo</button></div></section>
  </template>

  <template v-else-if="tab==='releases'">
    <section class="grid cols-2"><article class="tool-card"><header><Tag :size="19"/><div><strong>Release Manager</strong><span>Tag, versão, notas, draft/prerelease/latest e publishing channels.</span></div></header><div class="grid cols-2"><label class="field"><span>Tag</span><input v-model="releaseForm.tag_name"/></label><label class="field"><span>Target</span><input v-model="releaseForm.target_commitish"/></label></div><label class="field"><span>Título</span><input v-model="releaseForm.name"/></label><label class="field"><span>Descrição</span><textarea v-model="releaseForm.body"/></label><div class="checks"><label class="check"><input v-model="releaseForm.create_tag" type="checkbox"/>Criar tag</label><label class="check"><input v-model="releaseForm.draft" type="checkbox"/>Draft</label><label class="check"><input v-model="releaseForm.prerelease" type="checkbox"/>Prerelease</label><label class="check"><input v-model="releaseForm.make_latest" type="checkbox"/>Latest</label></div><div class="channel-list"><label v-for="channel in channels" :key="channel.id" class="check"><input v-model="releaseForm.channel_ids" type="checkbox" :value="channel.id"/>{{channel.name}} · {{channel.kind}}</label></div><button class="button primary" :disabled="!selectedRepository" @click="createRelease"><Tag :size="15"/>Publicar release</button></article>
      <article class="tool-card"><header><Play :size="19"/><div><strong>Workflow Dispatch</strong><span>Executar workflow por arquivo ou ID.</span></div></header><label class="field"><span>Workflow</span><input v-model="workflowForm.workflow"/></label><label class="field"><span>Ref</span><input v-model="workflowForm.ref"/></label><div class="actions"><button class="button primary" @click="dispatchWorkflow"><Play :size="15"/>Executar</button><button class="button secondary" @click="loadActions">Atualizar Actions</button></div><hr/><label class="field"><span>Novo canal de publicação</span><div class="grid cols-2"><input v-model="channelForm.name"/><select v-model="channelForm.kind"><option value="github_release">GitHub Release</option><option value="github_repository">Outro repositório</option><option value="s3">S3</option><option value="minio">MinIO</option><option value="google_drive">Drive</option><option value="dropbox">Dropbox</option><option value="sftp">SFTP</option></select></div></label><button class="button ghost" @click="createChannel">Criar canal básico</button></article></section>
    <section class="stats-row"><article><span>Workflows</span><strong>{{actions.workflows.length}}</strong></article><article><span>Runs</span><strong>{{actions.runs.length}}</strong></article><article><span>Artifacts</span><strong>{{actions.artifacts.length}}</strong></article><article><span>Cache</span><strong>{{actions.caches.length}}</strong></article></section>
    <section class="tool-card wide"><header><Wrench :size="19"/><div><strong>Runs, Artifacts e Actions Cache</strong><span>Dados atuais do repositório selecionado.</span></div></header><div class="data-columns"><div><h4>Runs</h4><pre>{{JSON.stringify(actions.runs.slice(0,30),null,2)}}</pre></div><div><h4>Artifacts</h4><pre>{{JSON.stringify(actions.artifacts.slice(0,30),null,2)}}</pre></div><div><h4>Cache</h4><pre>{{JSON.stringify(actions.caches.slice(0,30),null,2)}}</pre></div></div></section>
  </template>

  <template v-else-if="tab==='ghcr'">
    <section class="tool-card wide"><header><Package :size="19"/><div><strong>GHCR Packages</strong><span>Owner user/org detectado no backend; nenhuma imagem precisa ser baixada localmente.</span></div></header><div class="grid cols-2"><label class="field"><span>Owner</span><input v-model="packageForm.owner"/></label><label class="field"><span>Package</span><input v-model="packageForm.package_name"/></label></div><div class="actions"><button class="button secondary" @click="loadPackages">Listar packages</button><button class="button primary" :disabled="!packageForm.package_name" @click="loadPackageDetail(packageForm.package_name)">Carregar package</button></div><div class="package-list"><button v-for="item in packages" :key="String(item.id||item.name)" @click="item.name&&loadPackageDetail(String(item.name))"><b>{{item.name}}</b><span>{{item.visibility||'—'}} · {{item.updated_at||item.created_at||'—'}}</span></button></div></section>
    <section v-if="packageDetail" class="tool-card wide"><header><div><strong>{{packageForm.owner}}/{{packageForm.package_name}}</strong><span>{{packageDetail.version_count}} versões · {{packageDetail.tag_count}} tags</span></div><button class="button ghost danger-text" @click="deletePackage">Excluir package</button></header><label class="field"><span>Tags a preservar em limpeza integral</span><input v-model="packageForm.preserve_tags" placeholder="latest, production, v1.5.0"/></label><div class="actions"><button class="button secondary" @click="deleteAllVersions">Excluir versões não preservadas</button></div><div class="table-wrap"><table><thead><tr><th>Version ID</th><th>Digest/Name</th><th>Tags</th><th>Criada</th><th></th></tr></thead><tbody><tr v-for="version in packageDetail.versions" :key="version.id"><td>{{version.id}}</td><td><code>{{version.name?.slice(0,32)||'—'}}</code></td><td><button v-for="tag in version.tags" :key="tag" class="tag-chip" @click="deleteByTag(tag)">{{tag}}</button><span v-if="!version.tags.length">untagged</span></td><td>{{version.created_at||'—'}}</td><td><button class="button ghost danger-text" @click="deleteVersion(version)">Excluir versão</button></td></tr></tbody></table></div></section>
  </template>

  <template v-else>
    <section class="cleanup-warning"><ShieldCheck :size="19"/><div><strong>Repository Cleanup Engine</strong><span>Analyze → Plan → Dry Run → Review → Backup → Confirm → Execute → Validate → Audit. Nenhuma exclusão automática por idade.</span></div></section>
    <section class="tool-card wide"><header><Trash2 :size="19"/><div><strong>Repository Analysis</strong><span>Critérios avulsos ou profiles podem ser gerenciados na Repository Clinic.</span></div></header><div class="grid cols-3"><label class="field"><span>Critérios JSON</span><textarea v-model="cleanupForm.criteriaText" class="mini-code"/></label><label class="field"><span>Preservação JSON</span><textarea v-model="cleanupForm.preservationText" class="mini-code"/></label><label class="field"><span>Checkpoint JSON</span><textarea v-model="cleanupForm.checkpointText" class="mini-code"/></label></div><div class="actions"><button class="button primary" :disabled="!selectedRepository" @click="analyzeCleanup"><Search :size="15"/>Analisar repositório</button><button class="button secondary" @click="refreshCleanup"><RefreshCw :size="15"/>Atualizar análises</button><RouterLink class="button ghost" to="/repository-clinic">Abrir Clínica completa</RouterLink></div></section>
    <section v-if="cleanupAnalyses.length" class="tool-card wide"><label class="field"><span>Análise</span><select v-model="selectedCleanupId" @change="refreshCleanup"><option v-for="item in cleanupAnalyses" :key="item.id" :value="item.id">{{item.reference}} · {{item.status}}</option></select></label><template v-if="selectedCleanup"><div class="facts"><span>{{selectedCleanup.status}}</span><span>{{selectedCleanup.candidates.length}} candidatos</span><span>{{bytes(selectedCleanup.estimated_reclaimed_bytes)}}</span></div><div class="actions"><button class="button ghost" @click="cleanupSelectedIds=selectedCleanup.candidates.filter(x=>!x.protected&&x.action_class==='safe').map(x=>x.id)">Selecionar SAFE</button><button class="button secondary" @click="cleanupDryRun">Dry Run</button><button class="button danger-button" :disabled="selectedCleanup.status!=='ready'" @click="cleanupExecute">Execute</button></div><div class="table-wrap"><table><thead><tr><th></th><th>Classe</th><th>Tipo</th><th>Recurso</th><th>Motivo</th></tr></thead><tbody><tr v-for="candidate in selectedCleanup.candidates" :key="candidate.id"><td><input v-model="cleanupSelectedIds" type="checkbox" :value="candidate.id" :disabled="candidate.protected"/></td><td>{{candidate.action_class}}</td><td>{{candidate.resource_type}}</td><td><code>{{candidate.resource_key}}</code></td><td>{{candidate.reason}}<small v-if="candidate.protected"> · PROTEGIDO</small></td></tr></tbody></table></div><pre v-if="Object.keys(selectedCleanup.dry_run||{}).length">{{JSON.stringify(selectedCleanup.dry_run,null,2)}}</pre></template></section>
  </template>
</div></template>

<style scoped>
